solution:
def bill(units):
    if units <= 0:
        return 0
    total = 50
    if units > 100:
        total += (min(units, 200) - 100) * 3
    if units > 200:
        total += (units - 200) * 6
    return total

alt:
def bill(units):
    if units == 0:
        return 0
    mid = max(0, min(units, 200) - 100)
    high = max(0, units - 200)
    return 50 + mid * 3 + high * 6
